style.css:
@-moz-document regexp(".*zabbix.*") {
/* NOTA: Si tu URL no tiene la palabra 'zabbix', cambia la línea de arriba 
       o configura la extensión para que aplique específicamente a tu dominio */

    .theme-dark {
        /* Paleta de Colores de Grafana */
        --body-bg-color: #111217 !important;       /* Fondo general */
        --form-bg-color: #181b21 !important;       /* Fondo de formularios y tarjetas */
        --background-color: #111217 !important;
        
        /* Contenedores y Tablas */
        --ui-bg-color: #181b21 !important;         /* Widgets de los Dashboards */
        --ui-border-color: #2c323d !important;     /* Bordes de las tablas y cajas */
        --table-border-color: #22252b !important;
        
        /* Textos */
        --font-color: #c7d0d9 !important;          /* Texto principal */
        --font-alt-color: #7b8191 !important;      /* Texto secundario / fechas */
        --font-selected-color: #ffffff !important;
        
        /* Enlaces y Botones (El azul clásico de Grafana) */
        --link-color: #5794f2 !important;
        --link-hover-color: #73a6f5 !important;
        --link-active-color: #5794f2 !important;
        --btn-bg-color: #5794f2 !important;
        
        /* Menú Lateral Izquierdo */
        --sidebar-bg-color: #111217 !important;
        --sidebar-border-color: #2c323d !important;
        
        /* Encabezados de tablas y pestañas */
        --header-bg-color: #181b21 !important;
        --tab-bg-color: #181b21 !important;
        --tab-selected-bg-color: #2c323d !important;
    }

    /* Un pequeño ajuste extra para los gráficos nativos de Zabbix */
    .theme-dark .flickerfreescreen, 
    .theme-dark .dashboard-grid-widget-contents {
        background-color: #181b21 !important;
    }
}
